export type TemplatesListAllAdapter = Pick<
	HevyRequestEffectClient,
	"getExerciseTemplates"
>;

export interface TemplatesListAllDescriptor {
	readonly id: "templates.listAll";
	readonly safety: Extract<HevyOperationSafety, "read">;
}

export const templatesListAllDescriptor: TemplatesListAllDescriptor = {
	id: "templates.listAll",
	safety: "read",
};

export interface TemplatesListAllOperation {
	readonly descriptor: TemplatesListAllDescriptor;
	readonly effect: (
		options?: HevyExecutionOptions,
	) => Effect.Effect<
		TemplatesListAllResult,
		HevyRequestEffectError | PaginationMismatchError
	>;
	execute(options?: HevyExecutionOptions): Promise<ExerciseTemplate[]>;
}

export type TemplatesListAllResult = ExerciseTemplate[] & {
	readonly pageCount?: number;
};

export interface TemplatesSearchInput {
	readonly query: string;
	readonly maxPages: number;
}

export interface TemplatesSearchOutput {
	readonly matches: ExerciseTemplate[];
	readonly pages: number;
	readonly itemsScanned: number;
	readonly complete: boolean;
}

export interface TemplatesSearchDescriptor {
	readonly id: "templates.search";
	readonly safety: Extract<HevyOperationSafety, "read">;
}

export const templatesSearchDescriptor: TemplatesSearchDescriptor = {
	id: "templates.search",
	safety: "read",
};

export interface TemplatesSearchOperation {
	readonly descriptor: TemplatesSearchDescriptor;
	readonly effect: (
		input: TemplatesSearchInput,
		options?: HevyExecutionOptions,
	) => Effect.Effect<
		TemplatesSearchOutput,
		HevyRequestEffectError | PaginationMismatchError
	>;
	execute(
		input: TemplatesSearchInput,
		options?: HevyExecutionOptions,
	): Promise<TemplatesSearchOutput>;
}

const TEMPLATES_PAGE_SIZE = 100;

type TemplatesListCursor = {
	readonly page: number;
};

type TemplatesListPage = {
	readonly templates: ExerciseTemplate[];
};

type TemplatesSearchCursor = {
	readonly page: number;
};

type TemplatesSearchPage = {
	readonly templates: ExerciseTemplate[];
	readonly hasNextPage: boolean;
	readonly endOfList?: boolean;
};

function hasNextTemplatesPage(
	pageCount: number | undefined,
	page: number,
	templates: readonly ExerciseTemplate[],
): boolean {
	return (
		templates.length > 0 &&
		Predicate.isNumber(pageCount) &&
		Number.isSafeInteger(pageCount) &&
		pageCount > page
	);
}

export function createTemplatesGetOperation(
	adapter: TemplatesGetAdapter,
): TemplatesGetOperation {
	const effect = Effect.fn("operations.templates.get")(function* (
		input: TemplatesGetInput,
		options?: HevyExecutionOptions,
	) {
		const request =
			options === undefined
				? adapter.getExerciseTemplate(input.exerciseTemplateId)
				: adapter.getExerciseTemplate(input.exerciseTemplateId, options);
		return yield* request.pipe(
			Effect.map((exerciseTemplate) => ({
				exerciseTemplate: isEmptyResponse(exerciseTemplate)
					? null
					: (exerciseTemplate ?? null),
				exerciseTemplateId: input.exerciseTemplateId,
			})),
			Effect.catchIf(
				(error) => isExpectedReadNotFound(error, "/v1/exercise_templates"),
				() =>
					Effect.succeed({
						exerciseTemplate: null,
						exerciseTemplateId: input.exerciseTemplateId,
						expected404Outcome: "not_found" as const,
					}),
			),
		);
	});

	const operation: TemplatesGetOperation = {
		descriptor: templatesGetDescriptor,
		effect,
		execute(input, options) {
			return Effect.runPromise(operation.effect(input, options));
		},
	};
	return operation;
}

function isEmptyResponse<T extends object>(
	response: T | null | undefined,
): response is T & Record<never, never> {
	return (
		response !== null &&
		response !== undefined &&
		Object.keys(response).length === 0
	);
}

export function createTemplatesHistoryOperation(
	adapter: TemplatesHistoryAdapter,
): TemplatesHistoryOperation {
	const effect = Effect.fn("operations.templates.history")(function* (
		input: TemplatesHistoryInput,
		options?: HevyExecutionOptions,
	) {
		const params = exerciseHistoryQuery(input);
		const request =
			options === undefined
				? adapter.getExerciseHistory(input.exerciseTemplateId, params)
				: adapter.getExerciseHistory(input.exerciseTemplateId, params, options);
		const response = yield* request;
		return {
			exerciseHistory: response?.exercise_history ?? [],
			exerciseTemplateId: input.exerciseTemplateId,
		};
	});

	const operation: TemplatesHistoryOperation = {
		descriptor: templatesHistoryDescriptor,
		effect,
		execute(input, options) {
			return Effect.runPromise(operation.effect(input, options));
		},
	};
	return operation;
}

export function createTemplatesCreateOperation(
	adapter: TemplatesCreateAdapter,
): TemplatesCreateOperation {
	const effect = Effect.fn("operations.templates.create")(function* (
		input: TemplatesCreateInput,
		options?: HevyExecutionOptions,
	) {
		const request =
			options === undefined
				? adapter.createExerciseTemplate(input)
				: adapter.createExerciseTemplate(input, options);
		return yield* request;
	});

	const operation: TemplatesCreateOperation = {
		descriptor: templatesCreateDescriptor,
		effect,
		execute(input, options) {
			return Effect.runPromise(operation.effect(input, options));
		},
	};
	return operation;
}

export function createTemplatesListAllOperation(
	adapter: TemplatesListAllAdapter,
): TemplatesListAllOperation {
	const effect = Effect.fn("operations.templates.listAll")(function* (
		options?: HevyExecutionOptions,
	) {
		const pageStream = Stream.paginate<
			TemplatesListCursor,
			TemplatesListPage,
			HevyRequestEffectError | PaginationMismatchError
		>({ page: 1 }, (cursor) => {
			const params = { page: cursor.page, pageSize: TEMPLATES_PAGE_SIZE };
			const request =
				options === undefined
					? adapter.getExerciseTemplates(params)
					: adapter.getExerciseTemplates(params, options);
			return request.pipe(
				Effect.flatMap((response: GetV1ExerciseTemplates200) => {
					if (response?.page !== undefined && response.page !== cursor.page) {
						return Effect.fail(
							new PaginationMismatchError({
								requested: cursor.page,
								received: response.page,
								collection: "exerciseTemplates",
								message: `Exercise templates page mismatch: requested page ${cursor.page} but received page ${response.page}`,
							}),
						);
					}

					const templates = response?.exercise_templates ?? [];
					return Effect.succeed([
						[{ templates }],
						hasNextTemplatesPage(response?.page_count, cursor.page, templates)
							? Option.some({ page: cursor.page + 1 })
							: Option.none(),
					] as const);
				}),
				Effect.catchIf(
					(error) =>
						isExpectedReadEndOfList(
							error,
							"/v1/exercise_templates",
							cursor.page,
						),
					() =>
						Effect.succeed([[], Option.none<TemplatesListCursor>()] as const),
				),
			);
		});
		const pages = yield* Stream.runCollect(pageStream);
		const templates = pages.flatMap(
			(page) => page.templates,
		) as TemplatesListAllResult;
		Object.defineProperty(templates, "pageCount", {
			configurable: false,
			enumerable: false,
			value: pages.length,
			writable: false,
		});
		return templates;
	});

	const operation: TemplatesListAllOperation = {
		descriptor: templatesListAllDescriptor,
		effect,
		execute(options) {
			return Effect.runPromise(operation.effect(options));
		},
	};
	return operation;
}

export function createTemplatesSearchOperation(
	adapter: TemplatesListAllAdapter,
): TemplatesSearchOperation {
	const effect = Effect.fn("operations.templates.search")(function* (
		input: TemplatesSearchInput,
		options?: HevyExecutionOptions,
	) {
		const maxPages = Math.max(0, Math.min(input.maxPages, 100));
		const query = input.query.toLowerCase();
		const pageStream = Stream.paginate<
			TemplatesSearchCursor,
			TemplatesSearchPage,
			HevyRequestEffectError | PaginationMismatchError
		>({ page: 1 }, (cursor) => {
			if (cursor.page > maxPages) {
				return Effect.succeed([
					[] as ReadonlyArray<TemplatesSearchPage>,
					Option.none<TemplatesSearchCursor>(),
				] as const);
			}
			const params = { page: cursor.page, pageSize: TEMPLATES_PAGE_SIZE };
			const request =
				options === undefined
					? adapter.getExerciseTemplates(params)
					: adapter.getExerciseTemplates(params, options);
			return request.pipe(
				Effect.flatMap((response: GetV1ExerciseTemplates200) => {
					if (response?.page !== undefined && response.page !== cursor.page) {
						return Effect.fail(
							new PaginationMismatchError({
								requested: cursor.page,
								received: response.page,
								collection: "exerciseTemplates",
								message: `Exercise templates page mismatch: requested page ${cursor.page} but received page ${response.page}`,
							}),
						);
					}

					const pageCount = response?.page_count;
					const templates = response?.exercise_templates ?? [];
					if (
						!Predicate.isNumber(pageCount) ||
						!Number.isSafeInteger(pageCount) ||
						pageCount < 0 ||
						(pageCount === 0 && templates.length > 0) ||
						(pageCount > 0 && pageCount < cursor.page)
					) {
						return Effect.fail(
							new PaginationMismatchError({
								requested: cursor.page,
								received: Predicate.isNumber(pageCount) ? pageCount : -1,
								collection: "exerciseTemplates",
								message: "The API returned invalid pagination metadata",
							}),
						);
					}
					const hasNextPage = hasNextTemplatesPage(
						pageCount,
						cursor.page,
						templates,
					);
					return Effect.succeed([
						[
							{
								templates,
								hasNextPage,
							},
						],
						hasNextPage && cursor.page < maxPages
							? Option.some({ page: cursor.page + 1 })
							: Option.none(),
					] as const);
				}),
				Effect.catchIf(
					(error) =>
						isExpectedReadEndOfList(
							error,
							"/v1/exercise_templates",
							cursor.page,
						),
					() =>
						Effect.succeed([
							[
								{
									templates: [] as ExerciseTemplate[],
									hasNextPage: false,
									endOfList: true,
								},
							],
							Option.none<TemplatesSearchCursor>(),
						] as const),
				),
			);
		});
		const pages = yield* Stream.runCollect(pageStream);
		const scannedPages = pages.filter((page) => !page.endOfList);
		const matches = scannedPages.flatMap((page) =>
			page.templates.filter((template) =>
				template.title?.toLowerCase().includes(query),
			),
		);
		return {
			matches,
			pages: scannedPages.length,
			itemsScanned: scannedPages.reduce(
				(total, page) => total + page.templates.length,
				0,
			),
			complete:
				pages.at(-1)?.endOfList === true || pages.at(-1)?.hasNextPage !== true,
		};
	});

	const operation: TemplatesSearchOperation = {
		descriptor: templatesSearchDescriptor,
		effect,
		execute(input, options) {
			return Effect.runPromise(operation.effect(input, options));
		},
	};
	return operation;
}

import { HevyHttpError, NotFoundError } from "@hevy-mcp/hevy-client";
import type {
	CreateCustomExerciseRequestBody,
	ExerciseHistoryEntry,
	ExerciseTemplate,
	GetV1ExerciseHistoryExercisetemplateid200,
	GetV1ExerciseTemplates200,
	PostV1ExerciseTemplates200,
} from "@hevy-mcp/hevy-client/types";
import { Effect } from "effect";
import { describe, expect, it, vi } from "vitest";
import {
	createTemplatesCreateOperation,
	createTemplatesGetOperation,
	createTemplatesHistoryOperation,
	createTemplatesListAllOperation,
	createTemplatesSearchOperation,
	type TemplatesGetAdapter,
	type TemplatesListAllAdapter,
} from "./templates.js";

function notFound(endpoint: string): NotFoundError {
	return new NotFoundError({
		status: 404,
		method: "GET",
		endpoint,
		expected: true,
	});
}

function createGetAdapter(
	response: ExerciseTemplate | Error,
): TemplatesGetAdapter {
	const getExerciseTemplate: TemplatesGetAdapter["getExerciseTemplate"] = (
		_id,
		_options,
	) =>
		response instanceof Error
			? Effect.fail(response)
			: Effect.succeed(response);
	return { getExerciseTemplate };
}

describe("templates.get operation", () => {
	it("returns the template entity and id with a read descriptor", async () => {
		const getExerciseTemplate = vi.fn(() =>
			Effect.succeed<ExerciseTemplate>({ id: "template-1", title: "Bench" }),
		);
		const operation = createTemplatesGetOperation({ getExerciseTemplate });
		const options = { timeoutMs: 1_000 };

		await expect(
			Effect.runPromise(
				operation.effect({ exerciseTemplateId: "template-1" }, options),
			),
		).resolves.toEqual({
			exerciseTemplate: { id: "template-1", title: "Bench" },
			exerciseTemplateId: "template-1",
		});
		expect(operation.descriptor).toEqual({
			id: "templates.get",
			safety: "read",
		});
		expect(getExerciseTemplate).toHaveBeenCalledWith("template-1", options);
	});

	it("recovers only a member 404 as not_found", async () => {
		const operation = createTemplatesGetOperation(
			createGetAdapter(notFound("/v1/exercise_templates/template-1")),
		);

		await expect(
			Effect.runPromise(operation.effect({ exerciseTemplateId: "template-1" })),
		).resolves.toEqual({
			exerciseTemplate: null,
			exerciseTemplateId: "template-1",
			expected404Outcome: "not_found",
		});
	});

	it("fails collection and unrelated 404s", async () => {
		for (const endpoint of [
			"/v1/exercise_templates",
			"/v1/routine_folders/folder-1",
		]) {
			const error = notFound(endpoint);
			const operation = createTemplatesGetOperation(createGetAdapter(error));

			await expect(
				Effect.runPromise(
					operation.effect({ exerciseTemplateId: "template-1" }),
				),
			).rejects.toBe(error);
		}
	});
});

describe("templates.history operation", () => {
	it("forwards only supplied date bounds and execution options", async () => {
		const history: ExerciseHistoryEntry[] = [{ workout_id: "workout-1" }];
		const getExerciseHistory = vi.fn(
			(
				_id: string,
				_params?: {
					start_date?: string;
					end_date?: string;
				},
				_options?: { timeoutMs?: number },
			) =>
				Effect.succeed<GetV1ExerciseHistoryExercisetemplateid200>({
					exercise_history: history,
				}),
		);
		const operation = createTemplatesHistoryOperation({ getExerciseHistory });
		const options = { timeoutMs: 1_000 };

		await expect(
			Effect.runPromise(
				operation.effect(
					{
						exerciseTemplateId: "template-1",
						startDate: "2026-01-01T00:00:00.000Z",
					},
					options,
				),
			),
		).resolves.toEqual({
			exerciseHistory: history,
			exerciseTemplateId: "template-1",
		});
		expect(getExerciseHistory).toHaveBeenCalledWith(
			"template-1",
			{ start_date: "2026-01-01T00:00:00.000Z" },
			options,
		);
	});

	it("uses an empty query object when no date bounds are supplied", async () => {
		const getExerciseHistory = vi.fn(() =>
			Effect.succeed<GetV1ExerciseHistoryExercisetemplateid200>({
				exercise_history: [],
			}),
		);
		const operation = createTemplatesHistoryOperation({ getExerciseHistory });

		await expect(
			Effect.runPromise(operation.effect({ exerciseTemplateId: "template-1" })),
		).resolves.toEqual({
			exerciseHistory: [],
			exerciseTemplateId: "template-1",
		});
		expect(getExerciseHistory).toHaveBeenCalledWith("template-1", {});
	});

	it("does not turn a history 404 into a successful absence", async () => {
		const error = notFound("/v1/exercise_history/template-1");
		const getExerciseHistory = vi.fn(() => Effect.fail(error));
		const operation = createTemplatesHistoryOperation({ getExerciseHistory });

		await expect(
			Effect.runPromise(operation.effect({ exerciseTemplateId: "template-1" })),
		).rejects.toBe(error);
	});
});

describe("templates.create operation", () => {
	it("posts the caller create body through the Effect adapter", async () => {
		const body: CreateCustomExerciseRequestBody = {
			exercise: { title: "Bench", other_muscles: [] },
		};
		const created: PostV1ExerciseTemplates200 = { id: 123 };
		const createExerciseTemplate = vi.fn(() => Effect.succeed(created));
		const operation = createTemplatesCreateOperation({
			createExerciseTemplate,
		});

		await expect(Effect.runPromise(operation.effect(body))).resolves.toEqual(
			created,
		);
		expect(createExerciseTemplate).toHaveBeenCalledWith(body);
	});
});

describe("templates.listAll operation", () => {
	it("concatenates pages at the API page size and stops at page_count", async () => {
		const requests: Array<{
			readonly params: Parameters<
				TemplatesListAllAdapter["getExerciseTemplates"]
			>[0];
			readonly options: Parameters<
				TemplatesListAllAdapter["getExerciseTemplates"]
			>[1];
		}> = [];
		const responses: GetV1ExerciseTemplates200[] = [
			{
				page: 1,
				page_count: 3,
				exercise_templates: [{ id: "template-1" }],
			},
			{
				page: 2,
				page_count: 3,
				exercise_templates: [{ id: "template-2" }],
			},
			{
				page: 3,
				page_count: 3,
				exercise_templates: [{ id: "template-3" }],
			},
		];
		const options = { timeoutMs: 1_000 };
		const getExerciseTemplates = vi.fn((params, requestOptions) => {
			requests.push({ params, options: requestOptions });
			return Effect.succeed(responses[(params?.page ?? 1) - 1] ?? {});
		});
		const operation = createTemplatesListAllOperation({
			getExerciseTemplates,
		});

		const templates = await Effect.runPromise(operation.effect(options));
		expect(templates).toEqual([
			{ id: "template-1" },
			{ id: "template-2" },
			{ id: "template-3" },
		]);
		expect(templates.pageCount).toBe(3);
		expect(requests).toEqual([
			{ params: { page: 1, pageSize: 100 }, options },
			{ params: { page: 2, pageSize: 100 }, options },
			{ params: { page: 3, pageSize: 100 }, options },
		]);
	});

	it("stops on an empty page without requesting another page", async () => {
		const getExerciseTemplates = vi
			.fn<TemplatesListAllAdapter["getExerciseTemplates"]>()
			.mockImplementation((params) =>
				Effect.succeed(
					params?.page === 1
						? {
								page: 1,
								page_count: 4,
								exercise_templates: [{ id: "template-1" }],
							}
						: { page: params?.page, page_count: 4, exercise_templates: [] },
				),
			);
		const operation = createTemplatesListAllOperation({
			getExerciseTemplates,
		});

		await expect(Effect.runPromise(operation.effect())).resolves.toEqual([
			{ id: "template-1" },
		]);
		expect(getExerciseTemplates).toHaveBeenCalledTimes(2);
	});

	it("ends on a later-page 404 but fails on a first-page 404", async () => {
		const laterPageError = notFound("/v1/exercise_templates");
		const laterPageAdapter = {
			getExerciseTemplates: vi
				.fn<TemplatesListAllAdapter["getExerciseTemplates"]>()
				.mockImplementation((params) =>
					params?.page === 1
						? Effect.succeed({
								page: 1,
								page_count: 3,
								exercise_templates: [{ id: "template-1" }],
							})
						: Effect.fail(laterPageError),
				),
		};
		const laterPageOperation =
			createTemplatesListAllOperation(laterPageAdapter);

		await expect(
			Effect.runPromise(laterPageOperation.effect()),
		).resolves.toEqual([{ id: "template-1" }]);
		expect(laterPageAdapter.getExerciseTemplates).toHaveBeenCalledTimes(2);

		const firstPageError = notFound("/v1/exercise_templates");
		const firstPageOperation = createTemplatesListAllOperation({
			getExerciseTemplates: vi
				.fn<TemplatesListAllAdapter["getExerciseTemplates"]>()
				.mockReturnValue(Effect.fail(firstPageError)),
		});

		await expect(Effect.runPromise(firstPageOperation.effect())).rejects.toBe(
			firstPageError,
		);
	});

	it("does not recover a member-path 404 while listing", async () => {
		const error = new HevyHttpError("not found", {
			status: 404,
			method: "GET",
			endpoint: "/v1/exercise_templates/template-1",
		});
